// Hold src/services/plainSign.ts to the Python reference.
//
//   node scripts/check-plain-signing.mjs [path/to/plain-signing.json]
//
// Vectors come from siLNt helpers/_plain_signing_fixtures.py, generated by
// calling the same builder the /plain/spend endpoint calls. Regenerate them
// after any change to the fee formula, the output ordering or the signing, on
// either side.
//
// tx_hex IS compared here, unlike the Silent Payments runner: ECDSA is RFC 6979
// and embit's low-R grinding is reproducible, so the two implementations must
// agree byte for byte. A single differing byte is a different transaction.
//
// The destination script is checked against the one the CLIENT derives from the
// address, not the one the plan carries. That is the point of deriving it on
// the device — a client that pays whatever script it is handed has moved the
// keys off the server and left the destination behind.

import { readFileSync } from 'node:fs';
import { register } from 'node:module';
import { pathToFileURL } from 'node:url';

// plainSign.ts imports its siblings without a file extension, as the app's
// bundlers expect. Teach Node the same before importing it.
register('./ts-resolve.mjs', import.meta.url);

// Relative to this file, i.e. thrilla/scripts/ -> the sibling siLNt checkout.
const FIXTURES = process.argv[2] || '../../siLNt/fixtures/plain-signing.json';

let failed = 0;
function ok(name, cond, detail = '') {
  console.log((cond ? '  ok   ' : '  FAIL ') + name);
  if (!cond) {
    if (detail) console.log('         ' + detail);
    failed++;
  }
}

const { buildSignedPlainTx, __testing } = await import(
  pathToFileURL(new URL('../src/services/plainSign.ts', import.meta.url).pathname).href
);
const { addressToScriptPubKey } = await import(
  pathToFileURL(new URL('../src/services/btcAddress.ts', import.meta.url).pathname).href
);
const { computePlainAmounts, outputVbytes, toHex, fromHex } = __testing;

const data = JSON.parse(readFileSync(new URL(FIXTURES, import.meta.url), 'utf8'));

for (const c of data.cases) {
  console.log('\n' + c.name);
  const e = c.expected;

  // 1. The destination script, derived here from the address the user typed.
  //    For an ordinary address the plan's copy must agree; for a Silent
  //    Payment one the plan has no copy to agree with, and buildSignedPlainTx
  //    below derives it from the input keys.
  if (!e.plan.is_silent_payment) {
    let spk;
    try {
      spk = toHex(addressToScriptPubKey(c.destination, c.network));
    } catch (err) {
      spk = `threw: ${err}`;
    }
    ok('destination script derived from the address',
       spk === e.plan.destination_script,
       `js ${spk}\n         py ${e.plan.destination_script}`);
  } else {
    ok('plan carries no script for a Silent Payment destination',
       e.plan.destination_script === null);
  }

  // 2. The amounts, computed independently of the plan.
  const destVbytes = e.plan.is_silent_payment
    ? 43
    : outputVbytes(fromHex(e.plan.destination_script));
  let amounts;
  try {
    amounts = computePlainAmounts(c.utxos, c.amount, c.fee_rate, destVbytes);
  } catch (err) {
    ok('amounts', false, String(err));
    continue;
  }
  ok('fee', amounts.fee === e.fee, `js ${amounts.fee} py ${e.fee}`);
  ok('change', amounts.change === e.change, `js ${amounts.change} py ${e.change}`);
  ok('amount out', amounts.sendAmount === e.amount,
     `js ${amounts.sendAmount} py ${e.amount}`);
  ok('total input', amounts.totalInput === e.total_input);
  ok('vsize', amounts.vsize === e.vsize, `js ${amounts.vsize} py ${e.vsize}`);

  // 3. The whole transaction.
  let built;
  try {
    built = buildSignedPlainTx({
      destination: c.destination,
      utxos: c.utxos,
      keys: c.keys,
      amount: c.amount,
      feeRate: c.fee_rate,
      changeAddress: c.change_address ?? null,
      network: c.network,
    });
  } catch (err) {
    ok('build', false, String(err));
    continue;
  }
  ok('tx_hex is identical', built.tx_hex === e.tx_hex,
     `js ${built.tx_hex}\n         py ${e.tx_hex}`);
  ok('input order', JSON.stringify(built.swept_addresses) ===
     JSON.stringify(e.swept_addresses));
  ok('input count', built.input_count === e.input_count);
  ok('built fee matches', built.fee === e.fee);
  ok('built change matches', built.change === e.change);
  ok('built vsize matches', built.vsize === e.vsize);
  // The field the review step renames to `recipient` and prints above a Confirm
  // button. Blank there is how coins go out with nothing on screen saying where
  // (2026-10-07), and it has to come off the BUILT transaction rather than the
  // input field — a Silent Payments destination has no plan script to fall back
  // on, so this is the only copy that was checked before anything was signed.
  ok('destination comes back for the review step',
     built.destination === c.destination, `js ${built.destination}`);
}

// A wrong key must be refused rather than used. The check exists because a
// signature under the wrong key is a transaction the network drops with
// nothing to point at.
console.log('\nguards');
{
  const c = data.cases[0];
  const badKeys = Object.fromEntries(
    Object.keys(c.keys).map((a) => [a, 'ee'.repeat(32)]),
  );
  let threw = '';
  try {
    buildSignedPlainTx({
      destination: c.destination, utxos: c.utxos, keys: badKeys,
      amount: c.amount, feeRate: c.fee_rate,
      changeAddress: c.change_address ?? null, network: c.network,
    });
  } catch (err) {
    threw = String(err);
  }
  ok('a key that does not control the address is refused',
     /does not control it/.test(threw), threw || 'it built anyway');

  let missing = '';
  try {
    buildSignedPlainTx({
      destination: c.destination, utxos: c.utxos, keys: {},
      amount: c.amount, feeRate: c.fee_rate,
      changeAddress: c.change_address ?? null, network: c.network,
    });
  } catch (err) {
    missing = String(err);
  }
  ok('a missing key is refused', /No key on this device/.test(missing),
     missing || 'it built anyway');

  // An address for another network must not be paid: on mainnet that is real
  // money to an output nobody can spend.
  let wrongNet = '';
  try {
    addressToScriptPubKey('bc1qw508d6qejxtdg4y5r3zarvary0c5xw7kv8f3t4', 'signet');
  } catch (err) {
    wrongNet = String(err);
  }
  ok('a mainnet address is refused on signet', /not an address on this network/.test(wrongNet),
     wrongNet || 'it was accepted');

  let bad = '';
  try {
    addressToScriptPubKey('tb1qw508d6qejxtdg4y5r3zarvary0c5xw7kxpjzsy', 'signet');
  } catch (err) {
    bad = String(err);
  }
  ok('a bad checksum is refused', bad !== '', bad || 'it was accepted');
}

console.log();
if (failed) {
  console.log(`${failed} FAILED`);
  process.exit(1);
}
console.log('all checks passed — the client builds what the server builds');
